const bytes=s=>Uint8Array.from(s,c=>c.charCodeAt(0));
// Published independent example, Kermit Project packet reference, not a vector
// generated by this implementation: SOH + ! F test.txt C CR.
const example=bytes('\x01+!Ftest.txtC\r');
assert.deepEqual(packet(1,'F',bytes('test.txt')),example);
for(let split=0;split<=example.length;split++){
  const reader=new PacketReader(),out=[...reader.feed(example.slice(0,split)),...reader.feed(example.slice(split))];
  assert.deepEqual(out,[{sequence:1,type:'F',data:bytes('test.txt')}]);
}
assert.equal(new PacketReader().feed(bytes('\x01 !Dignore'))[0].error,'Unsupported or invalid Kermit packet length.');
const corrupt=example.slice();corrupt[5]^=1;
assert.equal(new PacketReader().feed(corrupt).length,1);
assert(new PacketReader().feed(corrupt)[0].error);
{
  assert.equal(new PacketReader().feed(example.subarray(0,-1))[0].type,'F','Generic Kermit remains length framed');
  const r=new PacketReader({end:13});assert.deepEqual(r.feed(example.subarray(0,-1)),[],'HP USB packets must not overtake the peer terminator');
  assert.equal(r.feed(example.subarray(-1))[0].type,'F');
}
