assert.equal(MAX_FILE_BYTES,2097152);
// HP USB is a character stream over bulk packets. Enumeration alone is not
// readiness: hold the first OUT until a complete, valid peer initialization.
function usbFixture(){
  const incoming=[],sent=[],events=[];
  const usb={endpoint:()=>({maxPacket:64}),send:b=>{sent.push(b.slice());return {result:0,accepted:b.length};},
    read:()=>incoming.length?{result:0,bytes:incoming.shift()}:{result:1}};
  const core={timebase_hz:()=>1000};
  const transfer=new FileTransfer({core,usb,model:4,notify:e=>events.push(e)});
  return {transfer,incoming,sent,events};
}
{
  const {transfer:f,incoming,sent}=usbFixture();
  f.start({request:1,transport:'usb',mode:'send',name:'A',bytes:bytes('HPHP49-Cdata')},0);
  f.poll(6000);assert(f.active);assert.equal(sent.length,0,'No early S, including its normal 5-second retry boundary');
  const bad=packet(0,'N');bad[4]^=1;incoming.push(bad);f.poll(6001);assert.equal(sent.length,0);
  incoming.push(packet(1,'N'));f.poll(6002);assert.equal(sent.length,0,'Unrelated sequence cannot open the first-write gate');
  const ready=packet(0,'N');incoming.push(ready.subarray(0,-1));f.poll(6003);assert.equal(sent.length,0,'Checksum alone does not finish HP USB reception');
  incoming.push(ready.subarray(-1));f.poll(6004);assert.equal(sent.length,0,'The final IN ACK must get one ordinary guest slice');
  f.poll(6005);assert.equal(new PacketReader().feed(sent[0])[0].type,'S');
  f.cancel(6006);assert.equal(f.pending,false);assert.equal(f.usbReady,false);
  sent.length=0;f.start({request:2,transport:'usb',mode:'get',name:'A'},6007);assert.equal(sent.length,0,'Cancellation resets readiness');
  f.resetUsb(6008);assert.equal(f.pending,false);assert.equal(f.usbReady,false);
}
for(const first of ['S','I']){
  const {transfer:f,incoming,sent,events}=usbFixture();
  f.start({request:1,transport:'usb',mode:'receive'},0);
  f.poll(6000);assert(f.active);assert.equal(sent.length,0,'Unwritten initial NAK does not prematurely time out');
  incoming.push(packet(0,first,PARAMETERS));f.poll(6001);f.poll(6002);
  assert.deepEqual(new PacketReader().feed(sent[0])[0],{sequence:0,type:'Y',data:PARAMETERS},'Initial peer S/I is processed and supersedes the unwritten NAK');
  if(first==='I'){incoming.push(packet(0,'S',PARAMETERS));f.poll(6003);}
  for(const p of [packet(1,'F',bytes('A')),packet(2,'D',bytes('abc')),packet(3,'Z'),packet(4,'B')]){incoming.push(p);f.poll(6004);}
  assert.equal(f.active,false);assert.equal(f.session.phase,'complete');
  assert.equal(events.filter(e=>e.type==='file-transfer-received').length,1);
}
{
  const {transfer:f,sent,events}=usbFixture();f.start({request:1,transport:'usb',mode:'receive'},0);
  f.poll(29999);assert(f.active);f.poll(30000);assert.equal(f.session.phase,'error');
  assert.equal(f.pending,false);assert.equal(sent.length,0);assert.equal(events.at(-1).active,false);
}
{
  const {transfer:f,incoming,sent}=usbFixture();f.usbReady=true;
  f.start({request:1,transport:'usb',mode:'finish'},0);
  incoming.push(packet(0,'Y',PARAMETERS));f.poll(1);
  incoming.push(packet(0,'Y'));f.poll(2);assert.equal(f.session.phase,'complete');assert.equal(f.usbReady,false);
  sent.length=0;f.start({request:2,transport:'usb',mode:'send',name:'A',bytes:bytes('HPHP49-Cdata')},3);
  f.poll(4);assert.equal(sent.length,0,'FINISH exits SERVER; the next operation must wait for it to start again');
}
{
  // A peer S may overtake a partially accepted initial NAK. Complete the
  // existing frame before ACKing S, rather than truncating that wire packet.
  const sent=[],r=new KermitSession({hz:1000,write:b=>{sent.push(b[0]);return 1;}});
  r.start({mode:'receive'},0);r.receive(packet(0,'S',PARAMETERS),1);
  for(let t=1;t<30;t++)r.poll(t);
  assert.deepEqual(new PacketReader().feed(Uint8Array.from(sent)).map(p=>p.type),['N','Y']);
}
